export const STORAGE_KEY='knowledge-lab-v3';
export function emptyState(){return{version:3,saved:[],drafts:{},records:{},notes:{},current:null};}
export function readState(storage){try{const a=JSON.parse(storage.getItem(STORAGE_KEY));if(a?.version!==3)return{state:emptyState(),error:null};if(!Array.isArray(a.saved)||!a.drafts||!a.records||typeof a.drafts!=='object'||typeof a.records!=='object'||Array.isArray(a.drafts)||Array.isArray(a.records))throw Error('invalid');return{state:{...emptyState(),...a},error:null};}catch{return{state:emptyState(),error:'이전 기록을 읽지 못했습니다. 새 학습은 계속할 수 있어요.'};}}
export function writeState(storage,state){try{storage.setItem(STORAGE_KEY,JSON.stringify(state));return null;}catch{return'저장 공간을 사용할 수 없습니다. 현재 화면에서는 학습을 계속할 수 있지만 새로고침하면 기록이 사라질 수 있어요.';}}
export function recordAnswer(state,item,choice,{review=false,initialChoice=null,now=Date.now()}={}){const previous=state.records[item.id]||{attempts:[],reviews:[]};const correct=choice===(review?(item.review||item.application).answer:item.answer),entry={choice,correct,at:now};if(!review&&Number.isInteger(initialChoice)){entry.initialChoice=initialChoice;entry.initialCorrect=initialChoice===item.answer;}const key=review?'reviews':'attempts';previous[key]=[...(previous[key]||[]),entry].slice(-30);previous.due=now+(correct?3:1)*86400000;state.records[item.id]=previous;return entry;}
export function dueItems(items,state,now=Date.now()){return items.filter(q=>state.records[q.id]?.due<=now);}
export function learningChange(record){if(!record)return'아직 풀지 않음';const first=record.attempts?.[0],firstCorrect=first?.initialCorrect??first?.correct;if(record.reviews?.at(-1)?.correct)return firstCorrect===false?'처음에는 놓쳤지만 새 상황에 적용했어요':'새 상황에서도 원리를 적용했어요';if(record.attempts?.at(-1)?.correct)return firstCorrect===false?'근거를 확인하고 판단을 수정했어요':'핵심 문제를 이해했어요';return'다른 상황에서 다시 확인할 원리';}
const inFlight=new Map();
export async function loadCatalog({fetcher=fetch,storage=localStorage,timeout=7000}={}){
 if(inFlight.has('catalog'))return inFlight.get('catalog');
 const work=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const lists=await Promise.all(['science','reasoning','humanities','perspectives','everyday'].map(async f=>{const response=await fetcher('./content/'+f+'.json',{signal:controller.signal,cache:'no-cache'});if(!response.ok)throw Error('콘텐츠 응답 실패');return response.json();}));const items=lists.flat();if(!items.length||items.some(q=>!q.id||!Array.isArray(q.options)||!q.sources?.length))throw Error('콘텐츠 형식 오류');try{storage.setItem('lab-content-cache-v3',JSON.stringify(items));}catch{}return{items,cached:false};}catch(e){try{const cache=JSON.parse(storage.getItem('lab-content-cache-v3'));if(Array.isArray(cache)&&cache.length&&cache.every(q=>q.id&&q.options&&q.sources))return{items:cache,cached:true};}catch{}throw Error('콘텐츠를 불러오지 못했습니다. 연결을 확인한 뒤 다시 시도해 주세요.');}finally{clearTimeout(timer);}})();inFlight.set('catalog',work);try{return await work;}finally{inFlight.delete('catalog');}
}
